INSERT INTO `products` (`id`, `category_id`, `title`, `slug`, `sku`, `short_description`, `description`, `benefits`, `directions`, `size_volume`, `price`, `compare_at_price`, `stock_quantity`, `low_stock_threshold`, `badge_text`, `skin_concern`, `routine_step`, `is_featured`, `is_best_seller`, `is_active`) VALUES
(1, 1, 'Vitamin C Brightening Face Serum', 'vitamin-c-brightening-face-serum', 'LYM-1001', 'Experience visible skin radiance with Lymko Vitamin C Brightening Face Serum. Lightweight, non-comedogenic, and suitable for all Indian skin types.', '<p>Formulated with high-potency bio-actives and Korean skincare philosophy, the <b>Vitamin C Brightening Face Serum</b> delivers targeted efficacy while respecting the skin''s moisture barrier.</p><ul><li>Promotes healthy cell turnover</li><li>Restores balanced hydration</li><li>Dermatologically tested and 100% cruelty-free</li></ul>', 'Hydrates deep layers · Enhances skin luminosity · Calms redness & inflammation · Protects against free radicals', 'Apply 2-3 drops onto freshly cleansed face and neck. Gently pat until absorbed. Follow with moisturizer and daytime sunscreen.', '30 ml', 499.00, 999.00, 150, 5, 'Save 50%', 'pigmentation', 'treat', 1, 1, 1),
