INSERT INTO `banners` (`id`, `title`, `subtitle`, `badge_text`, `button_text`, `button_url`, `desktop_image_url`, `bg_tint`, `sort_order`, `is_active`) VALUES
(1, 'Good skin. Better you.', 'Targeted botanical serums and daily rituals formulated for radiant, healthy Indian skin.', 'Skincare | Haircare', 'Shop Now', '/collections/all', 'https://lymko.in/cdn/shop/files/01_00038bd1-1c41-476d-9bcc-3d3055e5027f.jpg', '#f7f6f4', 1, 1),
(2, 'Curated Daily Rituals', 'Complete 4-step morning and evening routines designed to simplify your skincare journey.', 'Curated Sets', 'Explore Rituals', '/collections/rituals', 'https://lymko.in/cdn/shop/files/01_00038bd1-1c41-476d-9bcc-3d3055e5027f.jpg', '#fdeee6', 2, 1);
INSERT INTO `cms_pages` (`title`, `slug`, `content_html`, `meta_title`, `meta_description`, `is_active`) VALUES
('About Us', 'about-us', '<h2>Our Philosophy</h2><p>At Lymko, we believe skincare should be intuitive, effective, and grounded in transparent science. Inspired by minimalist Korean routines and tailored specifically for Indian skin climates, our formulations pair proven botanical extracts with high-efficacy active ingredients.</p><p>Every formula is crafted without parabens, sulfates, artificial dyes, or heavy synthetic fragrances. We are 100% cruelty-free and committed to sustainable, eco-conscious packaging.</p>', 'About Lymko Skincare', 'Learn about Lymko natural skincare, Korean inspiration, and our clean beauty mission.', 1),
('Shipping Policy', 'shipping', '<h2>Shipping Across India</h2><p>We are pleased to offer <b>Free Standard Shipping</b> on all orders across India, with no minimum purchase requirement.</p><p>Orders are dispatched from our fulfillment facility within 24-48 business hours. Typical delivery timelines range from 3 to 5 business days depending on your delivery postal pincode. Real-time SMS and email tracking links are provided once dispatched.</p>', 'Shipping Policy — lymko.in', 'Free standard shipping across India on all Lymko orders.', 1),
('Returns & Refund Policy', 'returns', '<h2>Hassle-Free 7-Day Returns</h2><p>We stand by the quality of our skincare formulations. If you receive a damaged, defective, or incorrect product, you are eligible for an immediate replacement or full refund within 7 days of delivery.</p><p>To initiate a return, reach out to our dedicated support team at <b>contact@lymko.in</b> or call <b>+91 88666 11621</b> with your order number and product photos.</p>', 'Return & Refund Policy — lymko.in', 'Our 7-day return policy and refund guidelines.', 1),
('Privacy Policy', 'privacy', '<h2>Your Privacy Matters</h2><p>This Privacy Policy explains how Lymko collects, uses, and safeguards your personal data when you browse our website or make a purchase. We use industry-standard SSL encryption and strict session controls. We never sell or share your personal data with third-party advertisers.</p>', 'Privacy Policy — lymko.in', 'Read about our data protection and privacy policies.', 1),
('Terms and Conditions', 'terms', '<h2>Terms of Service</h2><p>Welcome to Lymko. By accessing our website, browsing our catalog, or making a purchase, you agree to comply with our terms of service, payment procedures, and applicable laws in India.</p>', 'Terms of Service — lymko.in', 'Lymko store terms of service and user agreements.', 1),
('Sustainability', 'sustainability', '<h2>Every Drop a Ritual. Plant Your Tree.</h2><p>Our commitment to green beauty goes beyond packaging. For every ritual set purchased, Lymko plants a native sapling to help reforest rural India. We utilize recyclable glass containers and post-consumer recycled boxes for 100% eco-friendly fulfillment.</p>', 'Sustainability & Green Pledge — lymko.in', 'Learn about Lymko eco-friendly packaging and tree plantation initiative.', 1),
('Ingredients Glossary', 'ingredients', '<h2>Transparent Skin Science</h2><p>We believe you should know exactly what goes on your skin. Our key actives include <b>Vitamin C</b> (3-O-Ethyl Ascorbic Acid for gentle brightening), <b>Niacinamide 10%</b> (sebum regulation & pore refinement), <b>Sodium Hyaluronate</b> (multi-molecular deep hydration), and <b>Rice Water Ferment</b> (natural skin barrier nourishment).</p>', 'Ingredients Glossary — lymko.in', 'A complete guide to ingredients and scientific benefits used in Lymko products.', 1),
('Skincare Guide', 'skincare-guide', '<h2>Find Your Optimal Daily Routine</h2><p>Skincare works best when consistent and layered correctly. Always remember the golden rule: apply from thinnest to thickest texture (Cleanser &rarr; Toner &rarr; Serum &rarr; Moisturizer &rarr; Sunscreen).</p>', 'Skincare Guide & Journal — lymko.in', 'Step-by-step skincare guide and expert tips for healthy, glowing skin.', 1);
